                clauses.append(clause)
        return clauses

    def local_coherence(clauses):
        n = len(clauses[0])
        coherence = 0
        for i in range(n):
            for j in range(i + 1, n):
                count = sum(1 for clause in clauses if clause[i] != clause[j])
                coherence += count / (n - 1)
        return coherence / n

    def dpll(clauses, assignment=[]):
        if not clauses:
            return True
        literal = next(lit for lit in range(-n, n + 1) if lit not in assignment and -lit not in assignment)
        if literal > 0:
            assignment.append(literal)
        else:
            assignment.append(-literal)
        if dpll(clauses, assignment):
            return True
        assignment.pop()
        if literal > 0:
            assignment.append(-literal)
        else:
            assignment.append(literal)
        if dpll(clauses, assignment):
            return True
        assignment.pop()
        return False

    def combinations(iterable, r):
        pool = list(iterable)
        n = len(pool)
        if r > n:
            return
        indices = list(range(r))
        yield tuple(pool[i] for i in indices)
        while True:
            for i in reversed(range(r)):
                if indices[i] != i + n - r:
                    break
            else:
                return
            indices[i] += 1
            for j in range(i + 1, r):
                indices[j] = indices[j - 1] + 1
            yield tuple(pool[i] for i in indices)

    def path_length(clauses, assignment=[]):
        if not clauses:
            return 0
        literal = next(lit for lit in range(-n, n + 1) if lit not in assignment and -lit not in assignment)
        if literal > 0:
